using System.Linq;using UnityEngine;using UnityEditor;using LWS.TruckSports.Editor;
namespace LWS.TruckMinefield.Editor {public static class MinefieldEffectsAuthoring {
 public static void Install(MinefieldMatch m){var old=GameObject.Find("Bounded Minefield flight and landing effects");if(old!=null)Object.DestroyImmediate(old);var root=new GameObject("Bounded Minefield flight and landing effects").transform;var material=SportsChaosAuthoring.Flare(MinefieldAuthoring.Folder);m.flightTrails=new TrailRenderer[8];for(int i=0;i<8;i++){var g=new GameObject("Colored airborne trace "+i);g.transform.SetParent(root,false);var trail=g.AddComponent<TrailRenderer>();trail.sharedMaterial=material;trail.time=.65f;trail.startWidth=.18f;trail.endWidth=0;trail.minVertexDistance=.18f;trail.alignment=LineAlignment.View;trail.emitting=false;trail.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;trail.receiveShadows=false;m.flightTrails[i]=trail;}m.landPuffs=new ParticleSystem[4];for(int i=0;i<4;i++){var puff=new GameObject("Pooled terrain contact puff "+i).AddComponent<ParticleSystem>();puff.transform.SetParent(root,false);SportsChaosAuthoring.FixBlast(puff,material);var main=puff.main;main.startColor=new ParticleSystem.MinMaxGradient(new Color(.55f,.37f,.18f,.5f),new Color(.3f,.23f,.12f,.35f));main.startSpeed=new ParticleSystem.MinMaxCurve(1,3);main.startSize=new ParticleSystem.MinMaxCurve(.2f,.8f);main.startLifetime=new ParticleSystem.MinMaxCurve(.3f,.7f);m.landPuffs[i]=puff;}var plate=SportsEventAuthoring.Mat(MinefieldAuthoring.Folder,"Marker contrast plate",new Color(.008f,.018f,.025f,.82f));plate.shader=Shader.Find("Universal Render Pipeline/Unlit");plate.SetFloat("_Surface",1);plate.SetFloat("_ZWrite",0);plate.SetFloat("_SrcBlend",(float)UnityEngine.Rendering.BlendMode.SrcAlpha);plate.SetFloat("_DstBlend",(float)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);plate.SetFloat("_Cull",0);plate.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");plate.renderQueue=3000;foreach(var flag in m.blastFlags.Concat(m.landingFlags).Concat(m.bestFlags)){if(flag.shadow!=null)Object.DestroyImmediate(flag.shadow.gameObject);flag.shadow=null;if(flag.backing!=null)Object.DestroyImmediate(flag.backing.gameObject);var backing=GameObject.CreatePrimitive(PrimitiveType.Quad);backing.name="Compact marker contrast backing";Object.DestroyImmediate(backing.GetComponent<Collider>());backing.transform.SetParent(flag.caption.transform,false);backing.transform.localPosition=new Vector3(0,0,.035f);backing.GetComponent<Renderer>().sharedMaterial=plate;backing.GetComponent<Renderer>().shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;flag.backing=backing.transform;}
 if(m.feedback.clips.Length<8)m.feedback.clips=m.feedback.clips.Concat(new[]{AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckDockDiving/Audio/Ordinary applause.wav")}).ToArray();EditorUtility.SetDirty(m);}
